package com.smarthotel.dao;
import com.smarthotel.database.Database;import com.smarthotel.model.User;import java.sql.*;
public class UserDao { public User find(String u)throws SQLException{try(Connection c=Database.connect();PreparedStatement p=c.prepareStatement("SELECT id,username,password_hash,role FROM users WHERE username=?")){p.setString(1,u);try(ResultSet r=p.executeQuery()){return r.next()?new User(r.getInt(1),r.getString(2),r.getString(3),r.getString(4)):null;}}} public int create(String u,String hash,String role)throws SQLException{try(Connection c=Database.connect();PreparedStatement p=c.prepareStatement("INSERT INTO users(username,password_hash,role) VALUES(?,?,?)",Statement.RETURN_GENERATED_KEYS)){p.setString(1,u);p.setString(2,hash);p.setString(3,role);p.executeUpdate();try(ResultSet r=p.getGeneratedKeys()){r.next();return r.getInt(1);}}} }
